INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(0, 'abandon', '/əˈbændən/', 'verb', '{"zh-TW":["放棄；拋棄","遺棄"],"en":["to give up completely","to leave someone permanently"]}', '{"prefix":{"text":"a-","meaning":"away (離開)"},"root":{"text":"bandon","meaning":"control (控制)"},"logic":"離開控制，意即「放棄」。"}', 'abandon a plan/project/ship', '[{"en":"They had to abandon the project due to lack of funding.","zh-TW":"因資金不足，他們不得不放棄該計畫。"},{"en":"The crew abandoned the sinking ship.","zh-TW":"船員們棄船逃生。"}]', '{"noun":"abandonment","adjective":"abandoned"}', NULL, 3, 0),
(1, 'abide', '/əˈbaɪd/', 'verb', '{"zh-TW":["遵守；忍受"],"en":["to accept or obey a rule or decision"]}', '{"prefix":{"text":"a-","meaning":"on (在…上)"},"root":{"text":"bide","meaning":"wait/stay (等待/停留)"},"logic":"停留在規則上，即「遵守」。"}', 'abide by rules/laws/decisions', '[{"en":"All members must abide by the association''s rules.","zh-TW":"所有會員必須遵守協會規則。"},{"en":"We expect partners to abide by the agreement.","zh-TW":"我們期望合作夥伴遵守協議。"}]', NULL, NULL, 2, 1),
(2, 'ability', '/əˈbɪləti/', 'noun', '{"zh-TW":["能力；才能"],"en":["the power or skill to do something"]}', '{"root":{"text":"abil","meaning":"able (能夠)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"能夠的狀態，即「能力」。"}', 'ability to do sth', '[{"en":"She has the ability to solve complex problems.","zh-TW":"她有解決複雜問題的能力。"},{"en":"Leadership ability is essential for managers.","zh-TW":"領導能力對管理者至關重要。"}]', '{"adjective":"able","adverb":"ably"}', NULL, 3, 2),
(3, 'abolish', '/əˈbɒlɪʃ/', 'verb', '{"zh-TW":["廢除；廢止"],"en":["to officially end a law or system"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"ol","meaning":"grow (成長)"},"suffix":{"text":"-ish","meaning":"to make (使)"},"logic":"使離開成長，即「廢除」。"}', 'abolish a law/system/practice', '[{"en":"The government voted to abolish the outdated regulation.","zh-TW":"政府投票廢除了過時的法規。"},{"en":"Many countries have abolished the death penalty.","zh-TW":"許多國家已廢除死刑。"}]', '{"noun":"abolition"}', NULL, 3, 3),
(4, 'abolition', '/ˌæbəˈlɪʃn/', 'noun', '{"zh-TW":["廢除；廢止"],"en":["the act of officially ending something"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"ol","meaning":"grow (成長)"},"suffix":{"text":"-ition","meaning":"action (動作)"},"logic":"離開成長的動作，即「廢除」。"}', 'abolition of / call for abolition', '[{"en":"The abolition of trade barriers boosted exports.","zh-TW":"廢除貿易壁壘促進了出口。"},{"en":"Some advocate for the abolition of overtime caps.","zh-TW":"有些人提倡廢除加班上限。"}]', '{"verb":"abolish"}', NULL, 3, 4),
(5, 'about', '/əˈbaʊt/', 'preposition', '{"zh-TW":["關於；大約"],"en":["concerning","approximately","concerning; approximately"]}', NULL, 'think about / about to; about + 名詞/V-ing', '[{"en":"What is this meeting about?","zh-TW":"這個會議是關於什麼的？"},{"en":"There are about 200 employees.","zh-TW":"大約有200名員工。"},{"en":"The book is about history.","zh-TW":"這本書是關於歷史的。"},{"en":"There are about 50 people here.","zh-TW":"這裡大約有50個人。"}]', '{"preposition":"about","adverb":"about"}', NULL, 2, 5),
(6, 'above', '/əˈbʌv/', 'preposition', '{"zh-TW":["在…上方；超過","在…上面；超過","在...上方；超過"],"en":["higher than","more than","in or to a higher position","at a higher level than; more than"]}', NULL, 'above all / above average; above all (最重要的是)', '[{"en":"Sales rose above expectations.","zh-TW":"銷售額超出了預期。"},{"en":"Above all, safety comes first.","zh-TW":"最重要的是，安全第一。"},{"en":"The temperature rose above 30 degrees.","zh-TW":"溫度升到了30度以上。"},{"en":"Above all, be honest.","zh-TW":"最重要的是，要誠實。"},{"en":"The plane flew above the clouds.","zh-TW":"飛機在雲層上方飛行。"},{"en":"Temperatures rose above 30 degrees.","zh-TW":"氣溫升超過30度。"}]', '{"preposition":"above","adjective":"above-mentioned"}', NULL, 2, 6),
(7, 'absence', '/ˈæbsəns/', 'noun', '{"zh-TW":["缺席；不在","缺乏"],"en":["the state of being away","the lack of something"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"sens","meaning":"be (存在)"},"logic":"離開存在的狀態，即「缺席」。"}', 'in the absence of / leave of absence', '[{"en":"In the absence of the manager, the assistant took charge.","zh-TW":"經理不在時，助理負責管理。"},{"en":"She took a leave of absence for personal reasons.","zh-TW":"她因私人原因請假。"}]', '{"adjective":"absent"}', NULL, 3, 7),
(8, 'absorb', '/əbˈzɔːrb/', 'verb', '{"zh-TW":["吸收","全神貫注"],"en":["to take in or soak up","to occupy attention fully"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"sorb","meaning":"suck (吸)"},"logic":"把東西吸走，即「吸收」。"}', 'absorb information/costs; absorb information / absorb moisture', '[{"en":"The company will absorb the extra shipping costs.","zh-TW":"公司將承擔額外的運費。"},{"en":"She was completely absorbed in her research.","zh-TW":"她完全沉浸在研究中。"},{"en":"Plants absorb carbon dioxide from the air.","zh-TW":"植物從空氣中吸收二氧化碳。"},{"en":"She quickly absorbed all the new information.","zh-TW":"她很快吸收了所有新資訊。"}]', '{"noun":"absorption","adjective":"absorbing"}', NULL, 2, 8),
(9, 'abstract', '/ˈæbstrækt/', 'adjective', '{"zh-TW":["抽象的","摘要"],"en":["existing in thought but not physical","a summary of a document","existing in thought rather than having a physical existence"]}', '{"prefix":{"text":"abs-","meaning":"away (離開)"},"root":{"text":"tract","meaning":"draw (拉)"},"logic":"從具體中拉出來，即「抽象的」。"}', 'abstract concept/idea/art; abstract art / abstract concept', '[{"en":"The report includes an abstract summarizing key findings.","zh-TW":"報告包含一份摘要，概述了主要發現。"},{"en":"Abstract thinking is required for strategic planning.","zh-TW":"策略規劃需要抽象思維。"},{"en":"The painting is very abstract.","zh-TW":"這幅畫非常抽象。"},{"en":"Justice is an abstract concept.","zh-TW":"正義是一個抽象概念。"}]', '{"noun":"abstraction","adverb":"abstractly","verb":"abstract"}', NULL, 3, 9),
(10, 'abundant', '/əˈbʌndənt/', 'adjective', '{"zh-TW":["豐富的；大量的"],"en":["existing in large quantities; more than enough"]}', '{"prefix":{"text":"ab-","meaning":"over (超出)"},"root":{"text":"und","meaning":"wave (波浪)"},"suffix":{"text":"-ant","meaning":"having quality (具有特質)"},"logic":"如波浪般溢出，即「豐富的」。"}', 'abundant resources/supply/evidence', '[{"en":"The region has abundant natural resources.","zh-TW":"該地區擁有豐富的自然資源。"},{"en":"There is abundant evidence to support the claim.","zh-TW":"有大量證據支持這個說法。"}]', '{"noun":"abundance","adverb":"abundantly"}', NULL, 3, 10),
(11, 'academia', '/ˌækəˈdiːmiə/', 'noun', '{"zh-TW":["學術界"],"en":["the world of universities and scholarly research"]}', NULL, 'in academia / bridge between academia and industry', '[{"en":"She spent 10 years in academia before joining the firm.","zh-TW":"她在加入公司前在學術界待了10年。"},{"en":"We bridge the gap between academia and industry.","zh-TW":"我們搭建學術界與產業界之間的橋樑。"}]', '{"noun":"academia","adjective":"academic","adverb":"academically"}', NULL, 3, 11),
(12, 'academic', '/ˌækəˈdɛmɪk/', 'adjective', '{"zh-TW":["學術的"],"en":["relating to education and studying"]}', NULL, 'academic year / academic achievement', '[{"en":"Her academic performance is excellent.","zh-TW":"她的學業成績很優秀。"},{"en":"The academic year starts in September.","zh-TW":"學年從九月開始。"}]', '{"noun":"academia","noun2":"academy"}', NULL, 3, 12),
(13, 'accelerate', '/əkˈseləreɪt/', 'verb', '{"zh-TW":["加速；促進"],"en":["to increase in speed","to cause to happen sooner"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"celer","meaning":"speed (速度)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使朝向速度，即「加速」。"}', 'accelerate growth/development', '[{"en":"The company aims to accelerate its expansion into Asian markets.","zh-TW":"公司旨在加速擴展亞洲市場。"},{"en":"Technology has accelerated the pace of change.","zh-TW":"科技加速了變革的步伐。"}]', '{"noun":"acceleration"}', NULL, 4, 13),
(14, 'accept', '/əkˈsept/', 'verb', '{"zh-TW":["接受；認可"],"en":["to agree to receive something","to believe something to be true","to agree to receive; to believe something is true"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cept","meaning":"take (拿取)"},"logic":"朝向自己拿取，即「接受」。"}', 'accept an offer/invitation; accept an offer/invitation/responsibility', '[{"en":"She accepted the job offer without hesitation.","zh-TW":"她毫不猶豫地接受了工作邀約。"},{"en":"The board accepted the proposal unanimously.","zh-TW":"董事會一致通過了該提案。"},{"en":"She accepted the job offer.","zh-TW":"她接受了這份工作。"},{"en":"He refused to accept the blame.","zh-TW":"他拒絕接受指責。"}]', '{"noun":"acceptance","adjective":"acceptable"}', NULL, 2, 14),
(15, 'access', '/ˈækses/', 'noun', '{"zh-TW":["進入；使用權","存取"],"en":["the opportunity to approach or enter","the right to use something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cess","meaning":"go (走)"},"logic":"走向某處，即「進入、存取」。"}', 'access to information/system', '[{"en":"Employees have access to the company database.","zh-TW":"員工可以存取公司資料庫。"},{"en":"The building provides wheelchair access.","zh-TW":"該建築提供輪椅通道。"}]', '{"adjective":"accessible","noun":"accessibility"}', NULL, 2, 15),
(16, 'accommodate', '/əˈkɒmədeɪt/', 'verb', '{"zh-TW":["容納；適應","提供住宿"],"en":["to provide lodging or room for","to adjust to fit needs"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"commod","meaning":"fit (適合)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使適合，即「容納、適應」。"}', 'accommodate guests/needs/requests', '[{"en":"The hotel can accommodate up to 500 guests.","zh-TW":"該飯店可容納最多500位客人。"},{"en":"We will try to accommodate your schedule.","zh-TW":"我們會盡量配合您的時間表。"}]', '{"noun":"accommodation"}', NULL, 4, 16),
(17, 'accomplish', '/əˈkɒmplɪʃ/', 'verb', '{"zh-TW":["完成；達成"],"en":["to succeed in doing or completing something","to achieve or complete successfully"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"compli","meaning":"fill (填滿)"},"suffix":{"text":"-ish","meaning":"to make (使)"},"logic":"使填滿完成，即「完成」。"}', 'accomplish a goal/task/mission; accomplish a goal / accomplish a task', '[{"en":"She accomplished all her objectives ahead of schedule.","zh-TW":"她提前完成了所有目標。"},{"en":"What do you hope to accomplish this quarter?","zh-TW":"你希望這季度達成什麼？"},{"en":"She accomplished her goal of running a marathon.","zh-TW":"她達成了跑馬拉松的目標。"},{"en":"What do you hope to accomplish today?","zh-TW":"你今天希望完成什麼？"}]', '{"noun":"accomplishment"}', NULL, 4, 17),
(18, 'account', '/əˈkaʊnt/', 'noun', '{"zh-TW":["帳戶；帳目","描述；報告"],"en":["a record of money received and spent","a description of an event"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"count","meaning":"count (計算)"},"logic":"朝向計算，即「帳戶」。"}', 'bank account / on account of', '[{"en":"Please transfer the payment to our company account.","zh-TW":"請將款項匯入我們的公司帳戶。"},{"en":"She gave a detailed account of the incident.","zh-TW":"她詳細描述了該事件。"}]', '{"noun":"accountant","adjective":"accountable"}', NULL, 3, 18),
(19, 'accumulate', '/əˈkjuːmjəleɪt/', 'verb', '{"zh-TW":["累積；積聚"],"en":["to gather together or acquire an increasing amount"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cumul","meaning":"heap (堆積)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使堆積起來，即「累積」。"}', 'accumulate wealth/debt/experience', '[{"en":"He accumulated considerable wealth over the years.","zh-TW":"他多年來累積了可觀的財富。"},{"en":"Dust had accumulated on the unused equipment.","zh-TW":"未使用的設備上積了灰塵。"}]', '{"noun":"accumulation"}', NULL, 4, 19),
(20, 'accurate', '/ˈækjərət/', 'adjective', '{"zh-TW":["準確的；精確的","準確的"],"en":["correct in all details; exact","correct in all details"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cur","meaning":"care (注意)"},"suffix":{"text":"-ate","meaning":"having quality (具有特質)"},"logic":"朝向注意的，即「準確的」。"}', 'accurate information/data/description; accurate information / accurate prediction', '[{"en":"Please ensure that all data entries are accurate.","zh-TW":"請確保所有資料輸入準確無誤。"},{"en":"The forecast proved to be highly accurate.","zh-TW":"該預測被證明非常準確。"},{"en":"The report contains accurate data.","zh-TW":"報告包含準確的數據。"},{"en":"Her prediction turned out to be accurate.","zh-TW":"她的預測結果證明是準確的。"}]', '{"noun":"accuracy","adverb":"accurately"}', NULL, 3, 20),
(21, 'achieve', '/əˈtʃiːv/', 'verb', '{"zh-TW":["達成；實現"],"en":["to successfully reach a goal by effort"]}', '{"prefix":{"text":"a-","meaning":"to (朝向)"},"root":{"text":"chieve","meaning":"come to head (完成)"},"logic":"朝向完成，即「達成」。"}', 'achieve a goal/success/results', '[{"en":"The team achieved record sales this quarter.","zh-TW":"團隊本季度達成了創紀錄的銷售額。"},{"en":"She achieved her ambition of becoming CEO.","zh-TW":"她實現了成為執行長的抱負。"}]', '{"noun":"achievement","adjective":"achievable"}', NULL, 3, 21),
(22, 'acknowledge', '/əkˈnɒlɪdʒ/', 'verb', '{"zh-TW":["承認；確認","致謝","承認；答謝"],"en":["to accept or admit the truth of","to show that one has noticed","to accept or admit the truth of something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"knowledge","meaning":"knowledge (知識)"},"logic":"朝向知道，即「承認」。"}', 'acknowledge receipt/contribution; acknowledge a mistake / acknowledge receipt', '[{"en":"The company acknowledged the error in the report.","zh-TW":"公司承認了報告中的錯誤。"},{"en":"Please acknowledge receipt of this email.","zh-TW":"請確認收到此電子郵件。"},{"en":"He acknowledged his mistake.","zh-TW":"他承認了自己的錯誤。"}]', '{"noun":"acknowledgment"}', NULL, 4, 22),
(23, 'acquire', '/əˈkwaɪər/', 'verb', '{"zh-TW":["獲得；取得","收購","獲得；收購"],"en":["to buy or obtain something","to learn or develop a skill","to gain possession of something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"quire","meaning":"seek (尋求)"},"logic":"朝向尋求，即「獲得」。"}', 'acquire skills/knowledge/company; acquire knowledge / acquire a company', '[{"en":"The firm acquired a smaller competitor last year.","zh-TW":"該公司去年收購了一家較小的競爭對手。"},{"en":"She acquired fluency in three languages.","zh-TW":"她掌握了三種語言的流利程度。"},{"en":"She acquired fluency in three languages.","zh-TW":"她習得了三種語言的流利度。"},{"en":"The company acquired a smaller competitor.","zh-TW":"公司收購了一家較小的競爭者。"}]', '{"noun":"acquisition"}', NULL, 3, 23),
(24, 'acquisition', '/ˌækwɪˈzɪʃn/', 'noun', '{"zh-TW":["收購；獲得"],"en":["the purchase of one company by another","the act of obtaining something","the buying of a company","the process of gaining something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"quis","meaning":"seek (尋求)"},"suffix":{"text":"-ition","meaning":"action (動作)"},"logic":"朝向尋求的動作，即「收購」。"}', 'mergers and acquisitions / acquisition strategy; mergers and acquisitions / customer acquisition', '[{"en":"The acquisition was valued at $2 billion.","zh-TW":"此次收購估值為20億美元。"},{"en":"Customer acquisition costs have increased.","zh-TW":"客戶獲取成本增加了。"},{"en":"The acquisition was worth $2 billion.","zh-TW":"這次收購價值20億美元。"},{"en":"Customer acquisition costs are rising.","zh-TW":"客戶獲取成本正在上升。"}]', '{"verb":"acquire","noun":"acquisition"}', NULL, 4, 24),
(25, 'across', '/əˈkrɒs/', 'preposition', '{"zh-TW":["橫越；在對面","穿過；橫跨","橫越；穿過；在對面"],"en":["from one side to the other","from one side to the other; on the opposite side"]}', NULL, 'come across / across from; across the street / come across; across from (在...對面)', '[{"en":"The office is across from the station.","zh-TW":"辦公室在車站對面。"},{"en":"We expanded across the region.","zh-TW":"我們擴展到整個地區。"},{"en":"She walked across the bridge.","zh-TW":"她走過了那座橋。"},{"en":"I came across an old friend.","zh-TW":"我偶然遇到了一位老朋友。"},{"en":"She walked across the street.","zh-TW":"她走過馬路。"},{"en":"The store is across from the bank.","zh-TW":"商店在銀行對面。"}]', '{"preposition":"across"}', NULL, 2, 25),
(26, 'adapt', '/əˈdæpt/', 'verb', '{"zh-TW":["適應；改編"],"en":["to adjust to new conditions","to modify for a new purpose"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"apt","meaning":"fit (適合)"},"logic":"朝向適合，即「適應」。"}', 'adapt to changes/environment; adapt to / adapt a novel', '[{"en":"Employees must adapt to new technologies quickly.","zh-TW":"員工必須快速適應新技術。"},{"en":"The novel was adapted into a film.","zh-TW":"這部小說被改編成電影。"},{"en":"Animals must adapt to their environment.","zh-TW":"動物必須適應環境。"},{"en":"The novel was adapted into a film.","zh-TW":"這本小說被改編成電影。"}]', '{"noun":"adaptation","adjective":"adaptable"}', NULL, 2, 26),
(27, 'add', '/æd/', 'verb', '{"zh-TW":["增加；添加","增加；添加；補充說"],"en":["to put something with something else","to put something with another thing; to say something more"]}', NULL, 'add up / add to; add up (加總) / add to (增添)', '[{"en":"Add some sugar to my coffee.","zh-TW":"在我的咖啡裡加些糖。"},{"en":"The numbers don''t add up.","zh-TW":"這些數字加起來不對。"},{"en":"Please add your name to the list.","zh-TW":"請把你的名字加到名單上。"},{"en":"The rain added to our difficulties.","zh-TW":"雨水增加了我們的困難。"}]', '{"noun":"addition","adjective":"additional","adverb":"additionally"}', NULL, 1, 27),
(28, 'additional', '/əˈdɪʃənl/', 'adjective', '{"zh-TW":["額外的；附加的"],"en":["extra; more than what is usual or expected"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"dit","meaning":"give (給予)"},"suffix":{"text":"-ional","meaning":"relating to (有關的)"},"logic":"額外給予的，即「額外的」。"}', 'additional cost/information/support', '[{"en":"There will be an additional charge for express delivery.","zh-TW":"快遞將收取額外費用。"},{"en":"Do you need any additional information?","zh-TW":"您需要任何額外資訊嗎？"}]', '{"noun":"addition","adverb":"additionally"}', NULL, 4, 28),
(29, 'address', '/əˈdres/', 'verb', '{"zh-TW":["處理；解決","演講；致辭"],"en":["to deal with a problem or issue","to speak formally to a group"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"dress","meaning":"direct (引導)"},"logic":"朝向引導，即「處理；致辭」。"}', 'address an issue/concern/audience', '[{"en":"The CEO addressed the shareholders at the annual meeting.","zh-TW":"執行長在年度會議上向股東致辭。"},{"en":"We need to address this issue immediately.","zh-TW":"我們需要立即處理這個問題。"}]', NULL, NULL, 3, 29),
(30, 'adequate', '/ˈædɪkwət/', 'adjective', '{"zh-TW":["足夠的；適當的"],"en":["sufficient for a specific need or requirement","sufficient for a specific requirement"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"equ","meaning":"equal (相等)"},"suffix":{"text":"-ate","meaning":"having quality (具有)"},"logic":"朝向相等，即「足夠的」。"}', 'adequate supply/funding/preparation; adequate supply / adequate preparation', '[{"en":"The budget is barely adequate for the project.","zh-TW":"預算勉強夠用於該專案。"},{"en":"Ensure adequate ventilation in the workspace.","zh-TW":"確保工作空間有充足的通風。"},{"en":"The hotel room was adequate for our needs.","zh-TW":"飯店房間足以滿足我們的需求。"},{"en":"Make sure you have adequate insurance.","zh-TW":"確保你有足夠的保險。"}]', '{"noun":"adequacy","adverb":"adequately"}', NULL, 3, 30),
(31, 'adhere', '/ədˈhɪər/', 'verb', '{"zh-TW":["遵守；堅持","黏附"],"en":["to follow rules or guidelines closely","to stick firmly to a surface"]}', '{"prefix":{"text":"ad-","meaning":"to (朝向)"},"root":{"text":"here","meaning":"stick (黏)"},"logic":"朝向黏住，即「遵守、黏附」。"}', 'adhere to rules/policies/standards', '[{"en":"All employees must adhere to the company''s code of conduct.","zh-TW":"所有員工都必須遵守公司行為準則。"},{"en":"Please adhere to the safety guidelines at all times.","zh-TW":"請隨時遵守安全指南。"}]', '{"noun":"adherence","adjective":"adherent"}', NULL, 2, 31),
(32, 'adjacent', '/əˈdʒeɪsnt/', 'adjective', '{"zh-TW":["鄰近的；毗鄰的"],"en":["next to or near something"]}', '{"prefix":{"text":"ad-","meaning":"near (靠近)"},"root":{"text":"jac","meaning":"lie (躺)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"躺在旁邊的，即「鄰近的」。"}', 'adjacent to / adjacent building/room', '[{"en":"The parking lot is adjacent to the main building.","zh-TW":"停車場緊鄰主建築。"},{"en":"We booked adjacent conference rooms for the event.","zh-TW":"我們為活動預訂了相鄰的會議室。"}]', NULL, NULL, 3, 32),
(33, 'adjust', '/əˈdʒʌst/', 'verb', '{"zh-TW":["調整；校準","調整"],"en":["to alter slightly to achieve the desired result","to alter slightly to achieve a desired result"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"just","meaning":"right (正確)"},"logic":"朝向正確，即「調整」。"}', 'adjust settings/schedule/strategy; adjust settings / adjust to', '[{"en":"We need to adjust our strategy to meet market demands.","zh-TW":"我們需要調整策略以滿足市場需求。"},{"en":"The price has been adjusted for inflation.","zh-TW":"價格已根據通膨進行調整。"},{"en":"You can adjust the temperature with this dial.","zh-TW":"你可以用這個旋鈕調整溫度。"},{"en":"It took time to adjust to the new schedule.","zh-TW":"適應新時間表需要一些時間。"}]', '{"noun":"adjustment","adjective":"adjustable"}', NULL, 2, 33),
(34, 'administer', '/ədˈmɪnɪstər/', 'verb', '{"zh-TW":["管理；執行","施予"],"en":["to manage or direct","to give or apply formally","to manage or be responsible for"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"minister","meaning":"serve (服務)"},"logic":"朝向服務，即「管理」。"}', 'administer a program/test/policy; administer a program / administer medicine', '[{"en":"The HR department administers the benefits program.","zh-TW":"人力資源部門管理福利計畫。"},{"en":"The exam will be administered next Monday.","zh-TW":"考試將於下週一進行。"},{"en":"She administers the company''s finances.","zh-TW":"她管理公司的財務。"},{"en":"The nurse administered the medication.","zh-TW":"護理師給予了藥物。"}]', '{"noun":"administration","adjective":"administrative","noun2":"administrator"}', NULL, 4, 34),
(35, 'admire', '/ədˈmaɪər/', 'verb', '{"zh-TW":["欽佩；讚賞"],"en":["to regard with respect or warm approval"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"mire","meaning":"wonder (驚嘆)"},"logic":"朝向某事物驚嘆，即「欽佩」。"}', 'admire someone for / greatly admire', '[{"en":"I admire her courage and determination.","zh-TW":"我欽佩她的勇氣和決心。"},{"en":"Everyone admires his dedication to work.","zh-TW":"每個人都讚賞他對工作的奉獻。"}]', '{"noun":"admiration","adjective":"admirable","noun2":"admirer"}', NULL, 2, 35),
(36, 'admission', '/ədˈmɪʃn/', 'noun', '{"zh-TW":["入場；入學","承認"],"en":["the process of being allowed to enter","a confession that something is true"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"miss","meaning":"send (送)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"被送入的動作，即「入場」。"}', 'admission fee/requirements/process', '[{"en":"Admission to the conference is free for members.","zh-TW":"會員可免費參加會議。"},{"en":"The admission requirements include a bachelor''s degree.","zh-TW":"入學要求包括學士學位。"}]', '{"verb":"admit"}', NULL, 3, 36),
(37, 'admit', '/ədˈmɪt/', 'verb', '{"zh-TW":["承認；准許進入"],"en":["to agree something is true unwillingly","to agree that something is true; to allow to enter"]}', NULL, 'admit to / be admitted to; admit to + V-ing / be admitted to', '[{"en":"He admitted making a mistake.","zh-TW":"他承認犯了錯。"},{"en":"She was admitted to the hospital.","zh-TW":"她被送進了醫院。"},{"en":"He admitted making a mistake.","zh-TW":"他承認犯了一個錯誤。"}]', '{"noun":"admission","adjective":"admissible"}', NULL, 2, 37),
(38, 'adopt', '/əˈdɒpt/', 'verb', '{"zh-TW":["採用；採納","收養","採用；收養"],"en":["to start using a new method or idea","to legally take another''s child","to take up or start to use"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"opt","meaning":"choose (選擇)"},"logic":"朝向選擇，即「採用」。"}', 'adopt a policy/strategy/approach; adopt a policy / adopt a child', '[{"en":"The company adopted a new remote work policy.","zh-TW":"公司採用了新的遠端工作政策。"},{"en":"Several countries have adopted similar regulations.","zh-TW":"幾個國家已採用了類似法規。"},{"en":"The company adopted a new marketing strategy.","zh-TW":"公司採用了新的行銷策略。"},{"en":"They decided to adopt a child.","zh-TW":"他們決定領養一個孩子。"}]', '{"noun":"adoption","adjective":"adopted"}', NULL, 2, 38),
(39, 'advance', '/ədˈvɑːns/', 'verb', '{"zh-TW":["推進；前進","預付","前進；推進"],"en":["to move forward or make progress","to pay money before it is due","to move forward","to make progress"]}', '{"prefix":{"text":"ad-","meaning":"forward (向前)"},"root":{"text":"vance","meaning":"go (走)"},"logic":"向前走，即「推進」。"}', 'advance knowledge/career/payment; advance in career / advance payment / in advance', '[{"en":"Technology continues to advance at a rapid pace.","zh-TW":"技術持續快速進步。"},{"en":"Can you advance me next month''s salary?","zh-TW":"你可以預付我下個月的薪水嗎？"},{"en":"Technology continues to advance rapidly.","zh-TW":"科技持續快速進步。"},{"en":"Please pay in advance.","zh-TW":"請預先付款。"}]', '{"noun":"advancement","adjective":"advanced"}', NULL, 3, 39),
(40, 'advantage', '/ədˈvɑːntɪdʒ/', 'noun', '{"zh-TW":["優勢；利益"],"en":["a condition giving a greater chance of success"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vant","meaning":"before (在前)"},"suffix":{"text":"-age","meaning":"state (狀態)"},"logic":"在前面的狀態，即「優勢」。"}', 'competitive advantage / take advantage of', '[{"en":"Our competitive advantage lies in customer service.","zh-TW":"我們的競爭優勢在於客戶服務。"},{"en":"Take advantage of the early-bird discount.","zh-TW":"把握早鳥折扣的機會。"}]', '{"adjective":"advantageous"}', NULL, 3, 40),
(41, 'advertise', '/ˈædvətaɪz/', 'verb', '{"zh-TW":["做廣告；宣傳"],"en":["to describe a product in media to promote sales"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vert","meaning":"turn (轉向)"},"suffix":{"text":"-ise","meaning":"to make (使)"},"logic":"使人轉向注意，即「做廣告」。"}', 'advertise a product/position/service', '[{"en":"The company advertises heavily on social media.","zh-TW":"公司在社群媒體上大量做廣告。"},{"en":"The position was advertised in major newspapers.","zh-TW":"該職位在主要報紙上刊登廣告。"}]', '{"noun":"advertisement","noun2":"advertiser"}', NULL, 3, 41),
(42, 'advise', '/ədˈvaɪz/', 'verb', '{"zh-TW":["建議；勸告"],"en":["to give counsel or recommendations"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"vise","meaning":"see (看)"},"logic":"朝向看清楚，即「建議」。"}', 'advise sb to do / advise against', '[{"en":"I would advise you to review the contract carefully.","zh-TW":"我建議你仔細審閱合約。"},{"en":"The consultant advised against the merger.","zh-TW":"顧問建議不要進行合併。"}]', '{"noun":"advice","noun2":"adviser","adjective":"advisable"}', NULL, 2, 42),
(43, 'advocate', '/ˈædvəkeɪt/', 'verb', '{"zh-TW":["提倡；擁護"],"en":["to publicly support or recommend a cause"]}', '{"prefix":{"text":"ad-","meaning":"toward (朝向)"},"root":{"text":"voc","meaning":"call (呼叫)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"朝向呼叫支持，即「提倡」。"}', 'advocate for change/reform/rights', '[{"en":"She advocates for better working conditions.","zh-TW":"她提倡更好的工作條件。"},{"en":"Many experts advocate a gradual approach.","zh-TW":"許多專家提倡循序漸進的方式。"}]', '{"noun":"advocacy"}', NULL, 3, 43),
(44, 'affect', '/əˈfekt/', 'verb', '{"zh-TW":["影響；作用於"],"en":["to have an influence on; to cause a change in"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fect","meaning":"do/make (做)"},"logic":"朝向作用，即「影響」。"}', 'affect performance/outcome/health', '[{"en":"The economic downturn affected many businesses.","zh-TW":"經濟低迷影響了許多企業。"},{"en":"Weather conditions may affect delivery times.","zh-TW":"天氣狀況可能影響交貨時間。"}]', '{"noun":"effect"}', NULL, 2, 44),
(45, 'affection', '/əˈfekʃn/', 'noun', '{"zh-TW":["情感；喜愛"],"en":["a gentle feeling of fondness or love"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fect","meaning":"do/make (做)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"對某人產生感情的狀態。"}', 'show affection / deep affection', '[{"en":"She showed great affection for her grandchildren.","zh-TW":"她對孫子們表現出極大的喜愛。"},{"en":"He has a deep affection for his hometown.","zh-TW":"他對故鄉有深厚的感情。"}]', '{"adjective":"affectionate"}', NULL, 3, 45),
(46, 'affiliate', '/əˈfɪlieɪt/', 'verb', '{"zh-TW":["使隸屬；使加入","附屬機構"],"en":["to officially attach or connect to an organization"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"fili","meaning":"son (子)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使成為兒子般的關係，即「隸屬」。"}', 'affiliate with / affiliated company', '[{"en":"The institute is affiliated with a major university.","zh-TW":"該研究所隸屬於一所主要大學。"},{"en":"Our affiliate offices handle regional operations.","zh-TW":"我們的附屬辦公室處理區域業務。"}]', '{"noun":"affiliation"}', NULL, 3, 46),
(47, 'afford', '/əˈfɔːrd/', 'verb', '{"zh-TW":["負擔得起","提供"],"en":["to have enough money to pay for","to provide or supply"]}', '{"prefix":{"text":"af-","meaning":"toward (朝向)"},"root":{"text":"ford","meaning":"further (推進)"},"logic":"朝向推進足夠的，即「負擔得起」。"}', 'afford to buy/pay / can''t afford', '[{"en":"The company cannot afford to lose any more clients.","zh-TW":"公司承受不起再失去任何客戶。"},{"en":"The new location affords a beautiful view.","zh-TW":"新地點提供了美麗的景觀。"}]', '{"adjective":"affordable"}', NULL, 2, 47),
(48, 'affordable', '/əˈfɔːrdəbl/', 'adjective', '{"zh-TW":["負擔得起的"],"en":["inexpensive enough for most people"]}', '{"root":{"text":"afford","meaning":"provide (提供)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠負擔的。"}', 'affordable housing / affordable price', '[{"en":"We need more affordable housing in the city.","zh-TW":"我們城市需要更多平價住宅。"},{"en":"The restaurant offers good food at affordable prices.","zh-TW":"這家餐廳以實惠的價格提供美食。"}]', '{"verb":"afford"}', NULL, 4, 48),
(49, 'afraid', '/əˈfreɪd/', 'adjective', '{"zh-TW":["害怕的；恐怕","害怕的；擔心的"],"en":["feeling fear or anxiety","feeling fear; worried about something"]}', NULL, 'afraid of / I''m afraid; be afraid of / I''m afraid (that)...', '[{"en":"She is afraid of spiders.","zh-TW":"她怕蜘蛛。"},{"en":"I''m afraid I can''t help.","zh-TW":"恐怕我幫不了你。"},{"en":"I''m afraid we''re sold out.","zh-TW":"恐怕我們賣完了。"}]', NULL, NULL, 2, 49);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(50, 'afternoon', '/ˌɑːftəˈnuːn/', 'noun', '{"zh-TW":["下午"],"en":["the period between midday and evening"]}', NULL, 'in the afternoon / this afternoon', '[{"en":"The meeting is scheduled for this afternoon.","zh-TW":"會議安排在今天下午。"},{"en":"She usually takes a nap in the afternoon.","zh-TW":"她通常在下午小睡。"}]', NULL, NULL, 3, 50),
(51, 'again', '/əˈɡɛn/', 'adverb', '{"zh-TW":["再一次；又"],"en":["one more time"]}', NULL, 'once again / again and again', '[{"en":"Please try again later.","zh-TW":"請稍後再試。"},{"en":"Once again, thank you all.","zh-TW":"再次感謝大家。"}]', '{"adverb":"again"}', NULL, 2, 51),
(52, 'against', '/əˈɡɛnst/', 'preposition', '{"zh-TW":["反對；靠著"],"en":["in opposition to","leaning on"]}', NULL, 'against the rules / go against', '[{"en":"This is against company policy.","zh-TW":"這違反公司政策。"},{"en":"He leaned against the desk.","zh-TW":"他靠在書桌上。"}]', '{"preposition":"against"}', NULL, 3, 52),
(53, 'age', '/eɪdʒ/', 'noun', '{"zh-TW":["年齡；時代"],"en":["the number of years someone has lived"]}', NULL, 'at the age of / old age', '[{"en":"She started working at the age of 18.","zh-TW":"她18歲開始工作。"},{"en":"We live in the digital age.","zh-TW":"我們生活在數位時代。"}]', '{"verb":"age","adjective":"aged"}', NULL, 1, 53),
(54, 'agenda', '/əˈdʒendə/', 'noun', '{"zh-TW":["議程；待辦事項"],"en":["a list of items to be discussed at a meeting"]}', '{"root":{"text":"ag","meaning":"do (做)"},"suffix":{"text":"-enda","meaning":"things to be done (待做的事)"},"logic":"待做的事，即「議程」。"}', 'meeting agenda / on the agenda', '[{"en":"The first item on the agenda is the budget review.","zh-TW":"議程上的第一項是預算審查。"},{"en":"Please distribute the agenda before the meeting.","zh-TW":"請在會議前分發議程。"}]', NULL, NULL, 2, 54),
(55, 'aggressive', '/əˈɡresɪv/', 'adjective', '{"zh-TW":["積極進取的","侵略的","侵略性的；積極進取的"],"en":["pursuing goals forcefully","hostile or violent"]}', '{"prefix":{"text":"ag-","meaning":"toward (朝向)"},"root":{"text":"gress","meaning":"step (踏步)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"朝向踏步的，即「積極進取的」。"}', 'aggressive strategy/marketing/growth; aggressive behavior / aggressive marketing', '[{"en":"The firm adopted an aggressive expansion strategy.","zh-TW":"該公司採用了積極的擴張策略。"},{"en":"Aggressive marketing helped boost brand awareness.","zh-TW":"積極的行銷幫助提升了品牌知名度。"},{"en":"The dog became aggressive toward strangers.","zh-TW":"這隻狗對陌生人變得有攻擊性。"},{"en":"The company adopted an aggressive marketing strategy.","zh-TW":"公司採取了積極的行銷策略。"}]', '{"noun":"aggression","adverb":"aggressively"}', NULL, 4, 55),
(56, 'agree', '/əˈɡriː/', 'verb', '{"zh-TW":["同意；贊成","同意；一致"],"en":["to have the same opinion; to consent","to have the same opinion","to have the same opinion; to say yes"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"gree","meaning":"pleasing (令人滿意)"},"logic":"朝向令人滿意，即「同意」。"}', 'agree on/to/with / agree to terms; agree with / agree on; agree with sb / agree to do sth / agree on sth', '[{"en":"Both parties agreed to the terms of the contract.","zh-TW":"雙方同意了合約條款。"},{"en":"I agree with your assessment of the situation.","zh-TW":"我同意你對情況的評估。"},{"en":"I agree with your suggestion.","zh-TW":"我同意你的建議。"},{"en":"They agreed on a price.","zh-TW":"他們就價格達成了一致。"},{"en":"They agreed to postpone the meeting.","zh-TW":"他們同意延後會議。"}]', '{"noun":"agreement","adjective":"agreeable"}', NULL, 2, 56),
(57, 'agriculture', '/ˈæɡrɪkʌltʃər/', 'noun', '{"zh-TW":["農業"],"en":["the science or practice of farming"]}', '{"root":{"text":"agri","meaning":"field (田地)"},"suffix":{"text":"culture","meaning":"cultivation (耕作)"},"logic":"耕作田地，即「農業」。"}', 'agriculture industry / sustainable agriculture', '[{"en":"Agriculture is the main industry in this region.","zh-TW":"農業是這個地區的主要產業。"},{"en":"Modern agriculture relies heavily on technology.","zh-TW":"現代農業高度依賴技術。"}]', '{"adjective":"agricultural"}', NULL, 4, 57),
(58, 'ahead', '/əˈhɛd/', 'adverb', '{"zh-TW":["在前面；提前"],"en":["in front; in advance"]}', NULL, 'go ahead / ahead of time', '[{"en":"Go ahead, I''ll catch up.","zh-TW":"你先走，我趕上。"},{"en":"We finished ahead of schedule.","zh-TW":"我們提前完成了。"}]', NULL, NULL, 2, 58),
(59, 'aid', '/eɪd/', 'noun', '{"zh-TW":["援助；幫助"],"en":["help or support","financial or material assistance"]}', '{"root":{"text":"aid","meaning":"help (幫助)"},"logic":"直接表示「援助」。"}', 'financial aid / first aid / in aid of', '[{"en":"The government provided aid to flood victims.","zh-TW":"政府向洪災受害者提供援助。"},{"en":"Visual aids can enhance presentations.","zh-TW":"視覺輔助工具可以增強簡報效果。"}]', NULL, NULL, 1, 59),
(60, 'aim', '/eɪm/', 'verb', '{"zh-TW":["目標；瞄準","旨在"],"en":["to intend or plan","to point or direct toward a target"]}', '{"root":{"text":"aim","meaning":"estimate/direct (估算/指向)"},"logic":"指向某處，即「瞄準、旨在」。"}', 'aim to do / aim at / aim for', '[{"en":"We aim to increase revenue by 20% this year.","zh-TW":"我們的目標是今年營收增長20%。"},{"en":"The campaign is aimed at young professionals.","zh-TW":"該活動針對年輕專業人士。"}]', NULL, NULL, 1, 60),
(61, 'air', '/ɛr/', 'noun', '{"zh-TW":["空氣；氣氛","空氣；氣氛；航空"],"en":["the mixture of gases around the earth","the mixture of gases we breathe; the space above the ground"]}', NULL, 'fresh air / on the air; by air (搭飛機) / on the air (播出中)', '[{"en":"Open the window for fresh air.","zh-TW":"打開窗戶呼吸新鮮空氣。"},{"en":"The show is on the air now.","zh-TW":"節目正在播出。"},{"en":"The air quality is poor today.","zh-TW":"今天空氣品質很差。"},{"en":"The package was sent by air.","zh-TW":"包裹以航空寄送。"}]', NULL, NULL, 1, 61),
(62, 'aisle', '/aɪl/', 'noun', '{"zh-TW":["走道；通道"],"en":["a passage between rows of shelves or seats"]}', '{"root":{"text":"aisle","meaning":"passage (通道)"},"logic":"源自拉丁語 ala（翼），指建築內的側通道。"}', 'walk down the aisle / aisle seat', '[{"en":"You can find the cereal in aisle three.","zh-TW":"你可以在第三走道找到麥片。"},{"en":"She prefers an aisle seat on the plane.","zh-TW":"她偏好飛機上的走道座位。"}]', NULL, NULL, 2, 62),
(63, 'alert', '/əˈlɜːrt/', 'adjective', '{"zh-TW":["警覺的；警報"],"en":["quick to notice and respond to danger"]}', '{"root":{"text":"alert","meaning":"on the watch (警戒)"},"logic":"源自義大利語 all''erta（在瞭望台上）。"}', 'stay alert / alert system / high alert', '[{"en":"Drivers should stay alert at all times.","zh-TW":"駕駛人應隨時保持警覺。"},{"en":"The system sends an alert when errors occur.","zh-TW":"系統在發生錯誤時發送警報。"}]', '{"noun":"alert","verb":"alert"}', NULL, 2, 63),
(64, 'algorithm', '/ˈælɡərɪðəm/', 'noun', '{"zh-TW":["演算法"],"en":["a set of rules for solving a problem"]}', NULL, 'search algorithm / algorithm design', '[{"en":"The algorithm sorts data efficiently.","zh-TW":"這個演算法能有效地排序資料。"},{"en":"Social media algorithms control what you see.","zh-TW":"社群媒體演算法控制你看到的內容。"}]', '{"adjective":"algorithmic"}', NULL, 3, 64),
(65, 'alive', '/əˈlaɪv/', 'adjective', '{"zh-TW":["活著的；有生氣的","活著的；有活力的","活著的；活躍的"],"en":["living; not dead","full of energy","living; full of energy"]}', NULL, 'stay alive / come alive', '[{"en":"The tradition is still alive today.","zh-TW":"這個傳統至今仍然存在。"},{"en":"The market comes alive on weekends.","zh-TW":"市場在週末變得熱鬧起來。"},{"en":"He was found alive after three days.","zh-TW":"三天後他被發現還活著。"},{"en":"The city comes alive at night.","zh-TW":"城市在夜晚活躍起來。"},{"en":"He is lucky to be alive after the accident.","zh-TW":"他在事故後還活著很幸運。"},{"en":"The city comes alive at night.","zh-TW":"這座城市在夜晚變得活躍起來。"}]', '{"adjective":"alive"}', NULL, 2, 65),
(66, 'allocate', '/ˈæləkeɪt/', 'verb', '{"zh-TW":["分配；撥出","分配"],"en":["to distribute resources for a particular purpose","to distribute for a particular purpose"]}', '{"prefix":{"text":"al-","meaning":"toward (朝向)"},"root":{"text":"loc","meaning":"place (地方)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使朝向特定地方，即「分配」。"}', 'allocate funds/resources/budget; allocate resources / allocate funds', '[{"en":"The company allocated $2 million for R&D.","zh-TW":"公司撥出200萬美元用於研發。"},{"en":"Resources should be allocated based on priority.","zh-TW":"資源應根據優先順序分配。"},{"en":"The government allocated funds for education.","zh-TW":"政府撥款用於教育。"},{"en":"We need to allocate more time to this project.","zh-TW":"我們需要為這個專案分配更多時間。"}]', '{"noun":"allocation"}', NULL, 3, 66),
(67, 'allow', '/əˈlaʊ/', 'verb', '{"zh-TW":["允許；准許","允許；容許"],"en":["to give permission for","to make something possible","to let someone do something","to give permission; to make it possible"]}', '{"prefix":{"text":"al-","meaning":"toward (朝向)"},"root":{"text":"low","meaning":"approve (批准)"},"logic":"朝向批准，即「允許」。"}', 'allow sb to do / allow for; allow for / not allowed; allow sb to do sth / be allowed to', '[{"en":"The policy allows employees to work from home.","zh-TW":"該政策允許員工在家工作。"},{"en":"Please allow 3-5 business days for processing.","zh-TW":"請預留3-5個工作天處理。"},{"en":"Smoking is not allowed here.","zh-TW":"這裡不准吸煙。"},{"en":"Allow two weeks for delivery.","zh-TW":"請預留兩週送貨時間。"},{"en":"Smoking is not allowed here.","zh-TW":"這裡不允許吸菸。"},{"en":"Please allow two weeks for delivery.","zh-TW":"請預留兩週的配送時間。"}]', '{"noun":"allowance","adjective":"allowable"}', NULL, 2, 67),
(68, 'alone', '/əˈloʊn/', 'adjective', '{"zh-TW":["獨自的；單獨的","單獨的；獨自的","獨自的；單獨地"],"en":["without other people","without other people; only"]}', NULL, 'leave alone / stand alone; leave alone / all alone; leave sb alone / let alone (更不用說)', '[{"en":"She prefers to work alone.","zh-TW":"她偏好獨自工作。"},{"en":"You are not alone in this.","zh-TW":"你不是一個人面對這件事。"},{"en":"She lives alone.","zh-TW":"她獨自生活。"},{"en":"Leave me alone, please.","zh-TW":"請讓我一個人待著。"},{"en":"She lives alone in a small apartment.","zh-TW":"她獨自住在一間小公寓裡。"},{"en":"Leave me alone, please.","zh-TW":"請別打擾我。"}]', '{"adjective":"alone","adverb":"alone"}', NULL, 2, 68),
(69, 'along', '/əˈlɒŋ/', 'preposition', '{"zh-TW":["沿著；一起"],"en":["moving forward on"]}', NULL, 'along with / get along', '[{"en":"We walked along the river.","zh-TW":"我們沿著河邊散步。"},{"en":"She gets along with everyone.","zh-TW":"她和每個人都相處得很好。"}]', NULL, NULL, 2, 69),
(70, 'already', '/ɔːlˈrɛdi/', 'adverb', '{"zh-TW":["已經"],"en":["before now or a specified time","before now or before a particular time"]}', NULL, 'already done / already know; already + 完成式', '[{"en":"The report is already finished.","zh-TW":"報告已經完成了。"},{"en":"We have already discussed this.","zh-TW":"我們已經討論過這件事了。"},{"en":"I''ve already eaten lunch.","zh-TW":"我已經吃過午餐了。"},{"en":"She already knows the answer.","zh-TW":"她已經知道答案了。"},{"en":"I''ve already finished my homework.","zh-TW":"我已經完成作業了。"},{"en":"The train had already left when we arrived.","zh-TW":"我們到達時火車已經開走了。"}]', '{"adverb":"already"}', NULL, 3, 70),
(71, 'also', '/ˈɔːlsoʊ/', 'adverb', '{"zh-TW":["也；而且"],"en":["in addition; too"]}', NULL, 'also known as / but also', '[{"en":"He also speaks French.","zh-TW":"他也說法語。"},{"en":"She is not only smart but also kind.","zh-TW":"她不僅聰明而且善良。"}]', NULL, NULL, 1, 71),
(72, 'alter', '/ˈɔːltər/', 'verb', '{"zh-TW":["改變；修改"],"en":["to change or make different"]}', '{"root":{"text":"alter","meaning":"other (其他)"},"logic":"使成為其他樣子，即「改變」。"}', 'alter plans/design/course', '[{"en":"The company altered its marketing strategy.","zh-TW":"公司修改了行銷策略。"},{"en":"Circumstances may alter the timeline.","zh-TW":"情況可能改變時間表。"}]', '{"noun":"alteration","adjective":"alternate"}', NULL, 2, 72),
(73, 'alternative', '/ɔːlˈtɜːrnətɪv/', 'noun', '{"zh-TW":["替代方案；選擇"],"en":["one of two or more available possibilities"]}', '{"root":{"text":"alter","meaning":"other (其他)"},"suffix":{"text":"-ative","meaning":"relating to (有關的)"},"logic":"與其他有關的，即「替代方案」。"}', 'alternative solution/approach/option', '[{"en":"We need to find an alternative to the current supplier.","zh-TW":"我們需要找到目前供應商的替代方案。"},{"en":"What are the alternatives if the deal falls through?","zh-TW":"如果交易失敗，有什麼替代方案？"}]', '{"adverb":"alternatively"}', NULL, 4, 73),
(74, 'although', '/ɔːlˈðoʊ/', 'conjunction', '{"zh-TW":["雖然；儘管"],"en":["despite the fact that"]}', NULL, 'although... still; although = though (較口語)', '[{"en":"Although it rained, we went out.","zh-TW":"雖然下雨了，我們還是出門了。"},{"en":"Although tired, she kept working.","zh-TW":"雖然累了，她仍繼續工作。"},{"en":"Although it was raining, we went out.","zh-TW":"雖然在下雨，我們還是出去了。"},{"en":"Although expensive, the product is worth it.","zh-TW":"雖然貴，但這個產品值得。"}]', NULL, NULL, 3, 74),
(75, 'alumni', '/əˈlʌmnaɪ/', 'noun', '{"zh-TW":["校友"],"en":["former students of a school or university"]}', NULL, 'alumni association / alumni network', '[{"en":"The alumni donated to the school.","zh-TW":"校友們捐款給學校。"},{"en":"She joined the alumni association.","zh-TW":"她加入了校友會。"}]', NULL, NULL, 2, 75),
(76, 'always', '/ˈɔːlweɪz/', 'adverb', '{"zh-TW":["總是；一直"],"en":["at all times"]}', NULL, 'always available / as always', '[{"en":"He is always punctual.","zh-TW":"他總是很準時。"},{"en":"Customers always come first.","zh-TW":"客戶永遠是第一位的。"}]', '{"adverb":"always"}', NULL, 2, 76),
(77, 'amazing', '/əˈmeɪzɪŋ/', 'adjective', '{"zh-TW":["令人驚嘆的；了不起的"],"en":["extremely surprising or impressive"]}', NULL, 'amazing + 名詞 / It''s amazing that...', '[{"en":"The view from the top was amazing.","zh-TW":"從頂端看下去的景色令人驚嘆。"},{"en":"She did an amazing job on the project.","zh-TW":"她在專案中表現出色。"}]', '{"verb":"amaze","noun":"amazement","adverb":"amazingly"}', NULL, 3, 77),
(78, 'ambitious', '/æmˈbɪʃəs/', 'adjective', '{"zh-TW":["有野心的；雄心勃勃的"],"en":["having a strong desire to succeed","requiring great effort"]}', '{"root":{"text":"ambi","meaning":"go around (四處走)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿四處尋求機會的特質，即「有野心的」。"}', 'ambitious plan/goal/target; ambitious goal / ambitious plan', '[{"en":"The company set ambitious growth targets for next year.","zh-TW":"公司為明年設定了雄心勃勃的成長目標。"},{"en":"She is an ambitious young professional.","zh-TW":"她是一位有抱負的年輕專業人士。"},{"en":"She is an ambitious young woman.","zh-TW":"她是個有抱負的年輕女性。"},{"en":"The project is ambitious but achievable.","zh-TW":"這個計畫雄心勃勃但可實現。"}]', '{"noun":"ambition","adverb":"ambitiously"}', NULL, 3, 78),
(79, 'amend', '/əˈmend/', 'verb', '{"zh-TW":["修正；修訂"],"en":["to make changes to improve or correct","to make changes to a document or law"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"mend","meaning":"fault (過錯)"},"logic":"朝向修正過錯，即「修訂」。"}', 'amend a contract/law/policy; amend a law / amend the constitution', '[{"en":"The contract was amended to include new terms.","zh-TW":"合約被修訂以納入新條款。"},{"en":"Congress voted to amend the legislation.","zh-TW":"國會投票修正了該立法。"},{"en":"The committee voted to amend the proposal.","zh-TW":"委員會投票修正了提案。"},{"en":"The law was amended to include new provisions.","zh-TW":"法律被修訂以納入新條款。"}]', '{"noun":"amendment"}', NULL, 2, 79),
(80, 'amendment', '/əˈmɛndmənt/', 'noun', '{"zh-TW":["修正案"],"en":["a change made to a law or document"]}', NULL, 'constitutional amendment / first amendment', '[{"en":"The First Amendment protects free speech.","zh-TW":"第一修正案保護言論自由。"},{"en":"They proposed an amendment to the bill.","zh-TW":"他們提議修改法案。"}]', '{"verb":"amend"}', NULL, 3, 80),
(81, 'among', '/əˈmʌŋ/', 'preposition', '{"zh-TW":["在…之中","在...之中；之間"],"en":["in the middle of; surrounded by","in the middle of; between more than two"]}', NULL, 'among others / among the best; among others (其中)', '[{"en":"She is among the top candidates.","zh-TW":"她是頂尖的候選人之一。"},{"en":"Divide the tasks among the team.","zh-TW":"把任務分配給團隊成員。"},{"en":"She sat among her friends.","zh-TW":"她坐在朋友們中間。"},{"en":"He is among the best students.","zh-TW":"他是最好的學生之一。"},{"en":"She is popular among her colleagues.","zh-TW":"她在同事之間很受歡迎。"},{"en":"The cost was divided among the team members.","zh-TW":"費用在團隊成員之間分攤。"}]', '{"preposition":"among"}', NULL, 2, 81),
(82, 'amount', '/əˈmaʊnt/', 'noun', '{"zh-TW":["金額；數量"],"en":["a quantity of something","the total of two or more quantities"]}', '{"prefix":{"text":"a-","meaning":"toward (朝向)"},"root":{"text":"mount","meaning":"mountain (山)"},"logic":"朝向堆積如山，即「數量」。"}', 'a large/small amount of / total amount', '[{"en":"The total amount due is $5,000.","zh-TW":"應付總金額為5,000美元。"},{"en":"A significant amount of time was spent on research.","zh-TW":"大量時間被用於研究。"}]', NULL, NULL, 2, 82),
(83, 'analyze', '/ˈænəlaɪz/', 'verb', '{"zh-TW":["分析；解析","分析"],"en":["to examine something in detail to understand it","to examine in detail"]}', '{"root":{"text":"ana","meaning":"up/throughout (全面)"},"suffix":{"text":"-lyze","meaning":"loosen/break down (分解)"},"logic":"全面分解，即「分析」。"}', 'analyze data/results/trends; analyze data / analyze results', '[{"en":"The team will analyze the survey results next week.","zh-TW":"團隊將在下週分析調查結果。"},{"en":"We need to analyze market trends before launching.","zh-TW":"推出前我們需要分析市場趨勢。"},{"en":"Scientists analyzed the data carefully.","zh-TW":"科學家仔細分析了數據。"},{"en":"We need to analyze the market trends.","zh-TW":"我們需要分析市場趨勢。"}]', '{"noun":"analysis","adjective":"analytical","noun2":"analyst"}', NULL, 3, 83),
(84, 'angry', '/ˈæŋɡri/', 'adjective', '{"zh-TW":["生氣的","生氣的；憤怒的"],"en":["feeling strong displeasure","feeling or showing strong displeasure"]}', NULL, 'get angry / angry about; angry at / angry about; angry with/at sb / angry about sth', '[{"en":"The customer was angry about the delay.","zh-TW":"顧客對延誤感到生氣。"},{"en":"Don''t make hasty decisions when angry.","zh-TW":"生氣時不要做倉促的決定。"},{"en":"She was angry about the delay.","zh-TW":"她對延誤感到生氣。"},{"en":"Don''t be angry with me.","zh-TW":"別對我生氣。"},{"en":"He was angry about the delay.","zh-TW":"他對延誤感到憤怒。"}]', '{"adjective":"angry","noun":"anger","adverb":"angrily","verb":"anger"}', NULL, 2, 84),
(85, 'animal', '/ˈænɪməl/', 'noun', '{"zh-TW":["動物"],"en":["a living creature that is not a plant or human","a living creature that can move and feel"]}', NULL, 'wild animal / animal rights; domestic/wild animal', '[{"en":"Dogs are loyal animals.","zh-TW":"狗是忠誠的動物。"},{"en":"Many wild animals are endangered.","zh-TW":"許多野生動物瀕臨滅絕。"},{"en":"Dogs are popular domestic animals.","zh-TW":"狗是受歡迎的家畜。"},{"en":"Many wild animals are endangered.","zh-TW":"許多野生動物瀕臨絕種。"}]', NULL, NULL, 2, 85),
(86, 'announce', '/əˈnaʊns/', 'verb', '{"zh-TW":["宣布；公告","宣布；宣告","宣布"],"en":["to make a public or official statement","to make something known publicly","to make a public statement about something"]}', '{"prefix":{"text":"an-","meaning":"toward (朝向)"},"root":{"text":"nounce","meaning":"report (報告)"},"logic":"朝向報告，即「宣布」。"}', 'announce a decision/plan/merger; announce a decision / announce that; announce the results / announce a decision / officially announce', '[{"en":"The CEO announced the merger at a press conference.","zh-TW":"執行長在記者會上宣布了合併消息。"},{"en":"The results will be announced next Monday.","zh-TW":"結果將於下週一公布。"},{"en":"They announced the winner.","zh-TW":"他們宣布了獲勝者。"},{"en":"The company announced a new product.","zh-TW":"公司宣布了一款新產品。"},{"en":"The company announced record profits.","zh-TW":"公司宣布了創紀錄的利潤。"},{"en":"They will announce the winner tomorrow.","zh-TW":"他們明天將宣布得獎者。"}]', '{"noun":"announcement","noun2":"announcer"}', NULL, 3, 86),
(87, 'annual', '/ˈænjuəl/', 'adjective', '{"zh-TW":["年度的；每年的"],"en":["occurring once every year"]}', '{"root":{"text":"annu","meaning":"year (年)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"與年有關的，即「年度的」。"}', 'annual report/meeting/revenue; annual report / annual meeting / annual income', '[{"en":"The annual report shows a 15% increase in profit.","zh-TW":"年度報告顯示利潤增長了15%。"},{"en":"The annual conference is held in December.","zh-TW":"年度會議在十二月舉行。"},{"en":"The company holds its annual meeting in March.","zh-TW":"公司每年三月舉行年度會議。"},{"en":"What is your annual income?","zh-TW":"你的年收入是多少？"}]', '{"adverb":"annually"}', NULL, 2, 87),
(88, 'another', '/əˈnʌðər/', 'determiner', '{"zh-TW":["另一個；再一個"],"en":["one more; a different one"]}', NULL, 'one another / another way', '[{"en":"Would you like another cup of tea?","zh-TW":"你想再來一杯茶嗎？"},{"en":"Let''s try another approach.","zh-TW":"讓我們試試另一種方法。"}]', NULL, NULL, 3, 88),
(89, 'answer', '/ˈænsər/', 'noun', '{"zh-TW":["答案；回覆","答案；回答","回答；答案；接電話"],"en":["a reply","a solution","a reply to a question","a reply; to respond to a question or call"]}', NULL, 'in answer to / answer the phone; answer the phone / in answer to; answer the phone / answer a question / in answer to', '[{"en":"Please answer my email by Friday.","zh-TW":"請在週五前回覆我的電子郵件。"},{"en":"There is no easy answer to this.","zh-TW":"這個問題沒有簡單的答案。"},{"en":"I don''t know the answer.","zh-TW":"我不知道答案。"},{"en":"Please answer the phone.","zh-TW":"請接電話。"},{"en":"Please answer my question.","zh-TW":"請回答我的問題。"},{"en":"Nobody answered the door.","zh-TW":"沒人來應門。"}]', '{"noun":"answer","verb":"answer","adjective":"answerable"}', NULL, 2, 89),
(90, 'anticipate', '/ænˈtɪsɪpeɪt/', 'verb', '{"zh-TW":["預期；預料"],"en":["to expect or predict something"]}', '{"prefix":{"text":"anti-","meaning":"before (之前)"},"root":{"text":"cip","meaning":"take (拿)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"在之前就拿取（準備），即「預期」。"}', 'anticipate demand/problems/growth', '[{"en":"We anticipate strong demand for the new product.","zh-TW":"我們預期新產品會有強勁需求。"},{"en":"The delay was not anticipated.","zh-TW":"這個延遲是始料未及的。"}]', '{"noun":"anticipation"}', NULL, 4, 90),
(91, 'anxious', '/ˈæŋkʃəs/', 'adjective', '{"zh-TW":["焦慮的；擔心的"],"en":["feeling worried or nervous"]}', '{"root":{"text":"anx","meaning":"choke/distress (窒息/痛苦)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿痛苦不安的，即「焦慮的」。"}', 'feel anxious / anxious about', '[{"en":"She felt anxious about the job interview.","zh-TW":"她對工作面試感到焦慮。"},{"en":"He was anxious to hear the results.","zh-TW":"他急切地想知道結果。"}]', '{"noun":"anxiety","adverb":"anxiously"}', NULL, 3, 91),
