(94, 'anything', '/ˈɛniθɪŋ/', 'pronoun', '{"zh-TW":["任何事物"],"en":["any thing at all","any thing; it doesn''t matter what"]}', NULL, 'anything else / not anything; anything else / if anything', '[{"en":"Is there anything I can do?","zh-TW":"有什麼我能做的嗎？"},{"en":"She didn''t say anything.","zh-TW":"她什麼都沒說。"},{"en":"Is there anything I can help with?","zh-TW":"有什麼我可以幫忙的嗎？"},{"en":"I''ll do anything to pass the exam.","zh-TW":"我會做任何事來通過考試。"}]', NULL, NULL, 3, 94),
