(97, 'apartment', '/əˈpɑːrtmənt/', 'noun', '{"zh-TW":["公寓"],"en":["a residential unit in a building","a set of rooms for living in, usually on one floor of a building"]}', NULL, 'apartment complex / rent an apartment; apartment building / studio apartment', '[{"en":"She rents an apartment near the office.","zh-TW":"她在辦公室附近租了一間公寓。"},{"en":"The apartment comes fully furnished.","zh-TW":"這間公寓有全套家具。"},{"en":"They rented a two-bedroom apartment.","zh-TW":"他們租了一間兩房公寓。"},{"en":"The apartment complex has a swimming pool.","zh-TW":"這個公寓大樓有游泳池。"}]', '{"noun":"apartment"}', NULL, 3, 97),
(98, 'apparent', '/əˈpærənt/', 'adjective', '{"zh-TW":["明顯的；顯然的"],"en":["clearly visible or understood; obvious"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"par","meaning":"appear (出現)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"朝向出現的，即「明顯的」。"}', 'become apparent / for no apparent reason', '[{"en":"It became apparent that the project would exceed budget.","zh-TW":"很明顯該專案將超出預算。"},{"en":"The benefits are apparent to everyone involved.","zh-TW":"好處對所有相關人員都是顯而易見的。"}]', '{"adverb":"apparently"}', NULL, 3, 98),
(99, 'appeal', '/əˈpiːl/', 'verb', '{"zh-TW":["呼籲；上訴","吸引","吸引；呼籲；上訴"],"en":["to make a serious request","to be attractive or interesting","to attract or be interesting"]}', '{"prefix":{"text":"ap-","meaning":"toward (朝向)"},"root":{"text":"peal","meaning":"drive/push (推動)"},"logic":"朝向推動人，即「呼籲、吸引」。"}', 'appeal to / appeal a decision; appeal to / appeal a decision / sex appeal', '[{"en":"The product appeals to health-conscious consumers.","zh-TW":"該產品吸引注重健康的消費者。"},{"en":"The company plans to appeal the court''s decision.","zh-TW":"公司計劃對法院判決提出上訴。"},{"en":"The idea doesn''t appeal to me.","zh-TW":"這個想法不吸引我。"},{"en":"They appealed the court''s decision.","zh-TW":"他們對法院的判決提出上訴。"}]', '{"adjective":"appealing","noun":"appeal"}', NULL, 2, 99);